import zipfile,glob,re
for f in glob.glob('**/*.xls*',recursive=True):
  z=zipfile.ZipFile(f)
  for n in z.namelist():
    t=z.read(n).decode('utf8','ignore')
    for m in re.finditer(r'(?i)feed',t):
      s=re.sub(r'<[^>]+>',' ',t[max(0,m.start()-600):m.end()+800])
      print('==',f,n); print(re.sub(r'\s+',' ',s)); print()
"

